-- IT Asset Inventory
-- 899 records converted from the uploaded markdown table

CREATE TABLE IF NOT EXISTS it_asset_inventory (
    id INTEGER PRIMARY KEY,
    items VARCHAR(255),
    location VARCHAR(255),
    property_code VARCHAR(100),
    life_span VARCHAR(100),
    acquisition_date VARCHAR(50),
    disposal_method VARCHAR(255),
    remarks TEXT,
    issued_to VARCHAR(255)
);

